insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_21_v1'
from (values
('127.145.d.1.A',3,'A construction manager lists the steps of a remodel before starting. The list is part of:','["Project planning", "Final inspection", "Site cleanup", "Bid opening"]'::jsonb,0,'Planning identifies steps before work begins.','original'),
('127.145.d.1.A',4,'Which step should come first in the sequence of a building project?','["Paint the trim", "Define the scope of work", "Close out the permit", "Hang the drywall"]'::jsonb,1,'Scope comes before any task.','original'),
('127.145.d.1.B',3,'Before a framing crew starts, the manager must arrange lumber, tools, and:','["Spare furniture", "Movie tickets", "Workers", "Wedding guests"]'::jsonb,2,'Resources include labor, materials, and equipment.','original'),
('127.145.d.1.B',4,'A resource list for a deck project most likely includes materials, labor, and:','["Vacation days", "Tax returns", "Floor wax", "Equipment"]'::jsonb,3,'Equipment is the third resource category.','original'),
('127.145.d.1.C',3,'A schedule shows when each task starts and:','["Finishes", "Is painted", "Is insured", "Is forgotten"]'::jsonb,0,'Schedules give start and finish dates.','original'),
('127.145.d.1.C',4,'A bar chart that shows tasks over time is called a:','["Pie chart", "Gantt chart", "Venn diagram", "Scatter plot"]'::jsonb,1,'Gantt charts display schedules.','original'),
('127.145.d.2.A',3,'A manager checks whether a deck needs a permit by looking at:','["Sports scores", "Menus", "Local building codes", "Weather apps"]'::jsonb,2,'Codes say when permits are required.','original'),
('127.145.d.2.A',4,'Which area commonly has legal rules that affect a building job?','["Truck color", "Lunch breaks only", "Tool brand", "Zoning and setbacks"]'::jsonb,3,'Zoning limits what and where you can build.','original'),
('127.145.d.2.B',3,'To find the electrical code that applies to a job, a manager would consult the:','["Adopted code book or city office", "Sales flyer", "Phone game", "Yearbook"]'::jsonb,0,'Adopted codes are the legal source.','original'),
('127.145.d.2.B',4,'Which source tells you which edition of a code your city has adopted?','["A radio ad", "The local building department", "A tool catalog", "A social media post"]'::jsonb,1,'The building department sets the edition.','original'),
('127.145.d.2.C',3,'A code says a stair riser may not exceed a set height. Interpreting this means:','["Painting it", "Ignoring it", "Applying the limit to your stair design", "Hiding it"]'::jsonb,2,'Interpretation turns text into design decisions.','original'),
('127.145.d.2.C',4,'When two code sections seem to conflict, the manager should:','["Skip both", "Pick the cheaper one", "Guess", "Ask the building official"]'::jsonb,3,'The official has authority to interpret.','original'),
('127.145.d.3.A',3,'Weighing the risks and benefits of a new building product is called:','["Risk assessment", "Surveying", "Housekeeping", "Decorating"]'::jsonb,0,'Assessment compares risks and benefits.','original'),
('127.145.d.3.A',4,'A new roofing material is cheaper but untested. A careful manager would:','["Choose by color", "Weigh the savings against the risk of failure", "Buy it without research", "Ban all new products"]'::jsonb,1,'Balanced assessment.','original'),
('127.145.d.3.B',3,'Construction management affects society by providing:','["Only music", "Only toys", "Homes, schools, and roads", "Only advertising"]'::jsonb,2,'Built environment serves communities.','original'),
('127.145.d.3.B',4,'A poorly managed project can harm a community through:','["Lower taxes always", "Cleaner air always", "Better roads", "Delays, cost overruns, and unsafe conditions"]'::jsonb,3,'Bad management has public costs.','original'),
('127.145.d.4.A',3,'A problem-solving strategy begins by:','["Defining the problem", "Closing the job", "Buying materials", "Painting"]'::jsonb,0,'Define first, then solve.','original'),
('127.145.d.4.A',4,'A crew keeps finding the same measuring error. The best next step is to:','["Stop measuring", "Identify the root cause", "Blame the newest worker", "Ignore it"]'::jsonb,1,'Root causes prevent repeats.','original'),
('127.145.d.4.B',3,'Critical thinking means:','["Skipping analysis", "Accepting every claim", "Questioning evidence before accepting it", "Copying others"]'::jsonb,2,'Critical thinking tests claims.','original'),
('127.145.d.4.B',4,'Two suppliers quote very different prices for the same lumber grade. A critical thinker would:','["Pick the highest", "Pick the first quote", "Flip a coin", "Compare quality, delivery, and terms"]'::jsonb,3,'Compare the whole offer.','original'),
('127.145.d.4.C',3,'A decision matrix helps a manager:','["Compare options against criteria", "Sharpen saws", "Paint walls", "Order lunch"]'::jsonb,0,'Matrices score choices.','original'),
('127.145.d.4.C',4,'In a decision matrix, the options are scored against:','["Random numbers", "Weighted criteria such as cost and durability", "Truck mileage", "Worker nicknames"]'::jsonb,1,'Criteria drive the scoring.','original'),
('127.145.d.5.A',3,'A budget for a research and development build lists expected:','["Songs", "Birthdays", "Costs", "Photos"]'::jsonb,2,'Budgets list costs.','original'),
('127.145.d.5.A',4,'Which item belongs in a prototype budget?','["Parking tickets", "Weather forecasts", "Lunch menus of visitors", "Materials and labor hours"]'::jsonb,3,'Direct costs are budgeted.','original'),
('127.145.d.5.B',3,'One way to cut project cost without lowering quality is to reduce:','["Wasted material", "Permits", "Inspections", "Safety training"]'::jsonb,0,'Waste reduction saves money safely.','original'),
('127.145.d.5.B',4,'Ordering materials cut to length instead of on-site cutting mainly reduces:','["Permit fees", "Scrap and labor", "Code compliance", "Inspection needs"]'::jsonb,1,'Pre-cut saves waste.','original'),
('127.145.d.6.A',3,'A technical report should be written in a style that is:','["Funny only", "Vague and poetic", "Clear and factual", "Secret"]'::jsonb,2,'Technical writing is clear.','original'),
('127.145.d.6.A',4,'Which section of a technical report states what was found?','["Dedication", "Table of toppings", "Cover decoration", "Results"]'::jsonb,3,'Results report findings.','original'),
('127.145.d.6.B',3,'During a technical presentation, a speaker should:','["Use visuals and speak clearly", "Face the wall", "Read silently", "Mumble"]'::jsonb,0,'Good delivery needs clarity.','original'),
('127.145.d.6.B',4,'A slide in a presentation to a client should mainly:','["Be blank", "Support the spoken point with a simple visual", "Hold all spoken words", "Be unreadable"]'::jsonb,1,'Slides support the speaker.','original'),
('127.145.d.6.C',3,'A room is 12 feet by 15 feet. Its area is:','["54 square feet", "90 square feet", "180 square feet", "27 square feet"]'::jsonb,2,'12 x 15 = 180.','original'),
('127.145.d.6.C',4,'A slab is 20 ft by 10 ft by 0.5 ft thick. About how many cubic feet of concrete are needed?','["200", "10", "30", "100"]'::jsonb,3,'20 x 10 x 0.5 = 100.','original'),
('127.145.d.6.D',3,'Concrete gains strength as it:','["Cures", "Boils", "Freezes", "Dries only in sun"]'::jsonb,0,'Curing is a chemical hydration process.','original'),
('127.145.d.6.D',4,'Steel expands when heated, which matters in construction because it can:','["Stop rusting", "Change the length of structural members", "Turn to wood", "Become lighter"]'::jsonb,1,'Thermal expansion affects structures.','original'),
('127.145.d.7.A',3,'The customer''s expectations for a house are best learned by:','["Guessing", "Reading old ads", "Meeting and listening to the customer", "Skipping the meeting"]'::jsonb,2,'Listening reveals expectations.','original'),
('127.145.d.7.A',4,'A client says "modern and low maintenance." The manager should:','["Assume a style", "Choose the cheapest option", "Ignore the comment", "Ask follow-up questions to define those terms"]'::jsonb,3,'Clarify vague requests.','original'),
('127.145.d.7.B',3,'To check whether a design meets expectations, compare it to the:','["Customer''s stated requirements", "Weather", "Neighbor''s car", "Stock prices"]'::jsonb,0,'Requirements are the yardstick.','original'),
('127.145.d.7.B',4,'A walkthrough with the client before completion is used to:','["Add secret changes", "Confirm the work matches what was promised", "Avoid questions", "Delay payment"]'::jsonb,1,'Walkthroughs verify scope.','original'),
('127.145.d.7.C',3,'A customer survey after a job helps a company assess:','["Lumber prices", "Weather", "Satisfaction", "Truck tires"]'::jsonb,2,'Surveys measure satisfaction.','original'),
('127.145.d.7.C',4,'A pattern of complaints about late finishes suggests the company should improve its:','["Logo", "Uniform color", "Parking lot", "Scheduling"]'::jsonb,3,'Complaints point to process fixes.','original'),
('127.145.d.8.A',3,'A manager who needs to compare costs across many jobs might use:','["Spreadsheet software", "A wheelbarrow", "A level", "A paintbrush"]'::jsonb,0,'Spreadsheets handle data comparisons.','original'),
('127.145.d.8.A',4,'A drone used on a large site is an example of technology used to:','["Lay tile", "Survey progress from above", "Pour concrete", "Cut lumber"]'::jsonb,1,'Drones capture site data.','original'),
('127.145.d.8.B',3,'After using a new tool on a job, the manager evaluates it by asking whether it:','["Was loud", "Was heavy", "Improved speed, cost, or quality", "Looked shiny"]'::jsonb,2,'Evaluate against outcomes.','original'),
('127.145.d.8.B',4,'A software trial saved no time and caused errors. The manager should likely:','["Hide the trial", "Buy more licenses", "Ignore the results", "Reconsider adopting it"]'::jsonb,3,'Evidence guides adoption.','original'),
('127.145.d.8.C',3,'Which factor influences whether a small firm uses new technology?','["Cost", "Coffee brand", "Moon phase", "Paint color"]'::jsonb,0,'Cost limits adoption.','original'),
('127.145.d.8.C',4,'Worker training time can influence the use of new equipment because it:','["Lowers all costs", "Delays productivity at first", "Replaces all workers", "Removes safety needs"]'::jsonb,1,'Training has costs.','original'),
('127.145.d.9.A',3,'An accepted design process begins with identifying:','["The paint brand", "The truck", "The need or problem", "The final color"]'::jsonb,2,'Design starts with a need.','original'),
('127.145.d.9.A',4,'After brainstorming several ideas for a shelter design, the next step is to:','["Sell the ideas", "Build all of them", "Quit", "Select and refine the best idea"]'::jsonb,3,'Select, then refine.','original'),
('127.145.d.9.B',3,'A scale model of a building is used to:','["Visualize the design before building", "Avoid planning", "Replace the permit", "Cut costs to zero"]'::jsonb,0,'Models show the design.','original'),
('127.145.d.9.B',4,'A set of plans includes drawings such as the floor plan and:','["Menus", "Elevations", "Recipes", "Playlists"]'::jsonb,1,'Elevations show sides.','original'),
('127.145.d.9.C',3,'A design constraint is a:','["Free choice", "Bonus", "Limit the design must work within", "Final color"]'::jsonb,2,'Constraints limit options.','original'),
('127.145.d.9.C',4,'Which is a design criterion for a storage shed?','["It is someday", "It is a nice idea", "It looks old", "It must hold 500 pounds of tools"]'::jsonb,3,'Criteria are measurable requirements.','original'),
('127.145.d.10.A',3,'3D printing of houses is an example of an:','["Emerging technology in construction", "Hand tool", "Surveying chain", "Outdated method"]'::jsonb,0,'3D printing is emerging in building.','original'),
('127.145.d.10.A',4,'Building information modeling, or BIM, is used to:','["Weigh trucks", "Create shared 3D digital models of a project", "Mix mortar", "Sharpen saws"]'::jsonb,1,'BIM coordinates design data.','original'),
('127.145.d.10.B',3,'A new technology is more likely to be adopted if it:','["Is unsafe", "Is untested", "Saves money and time", "Costs more and slows work"]'::jsonb,2,'Benefits drive adoption.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
