('127.146.d.1.E',5,'A foreman gives a three-step instruction over a noisy saw. The best active-listening move is to:','["Move somewhere quieter and repeat the steps back", "Wait and ask a coworker later", "Nod and guess the steps", "Start work and fix errors afterward"]'::jsonb,0,'Confirm understanding.','original'),
('127.147.d.5.A',5,'A deck needs 24 joists. Waste allowance of 10 percent means the bill of materials should list how many joists?','["25", "27", "26", "30"]'::jsonb,1,'24 x 1.1 = 26.4, round up to 27.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
